51	export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
52	  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
53	  const isAtBottomRef = useRef(true);
54	  const lastEventKeyRef = useRef<string | undefined>(undefined);
55	  const lastBottomEventKeyRef = useRef<string | undefined>(undefined);
56	  const scrollTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
57	  const visibleHeightRef = useRef(0);
58	  const [showScrollDown, setShowScrollDown] = useState(false);
59	  const {
60	    events,
61	    isPaginatingRef,
62	    reachedStartRef,
63	    isDirect,
64	    loadMoreMessages,
65	    markAsRead,
66	  } = useRoomTimeline({
67	    room,
68	    roomId,
69	  });
70	  const [scrollToEventId, setScrollToEventId] = useAtom(
71	    TimelineAtoms.scrollToEventId,
72	  );
73	  const [seenByUsers, setSeenByUsers] = useAtom(TimelineAtoms.seenByUsers);
74	  const [reactionsPayload, setReactionsPayload] = useAtom(
75	    TimelineAtoms.reactionsPayload,
76	  );
77	  const [shieldPayload, setShieldPayload] = useAtom(TimelineAtoms.shieldPayload);
78	  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
79	    useRoomIdentityViolations(room);
80	  const {
81	    selectedMember,
82	    isBottomSheetOpen,
83	    openMemberDetails,
84	    closeMemberDetails,
85	  } = useMemberDetails();
86	
87	  const sortedEvents = useMemo(() => {
88	    const sorted = [...events].sort(
89	      (a, b) => Number(a.timestamp) - Number(b.timestamp),
90	    );
91	
92	    return filterSameStateKey(sorted);
93	  }, [events]);
94	
95	  const eventsWithDividers = useMemo(() => {
96	    const items = groupInfoEvents(addDateDividers(sortedEvents));
97	
98	    // Pre-compute isPreviousSameSender so it's not recalculated per-item during render
99	    let prevSender: string | null = null;
100	    for (const item of items) {
101	      if (item.type !== "event") {
102	        prevSender = null;
103	        continue;
104	      }
105	      const isMsgLike =
106	        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
107	      if (!isMsgLike) {
108	        prevSender = null;
109	        continue;
110	      }
111	      item.isPreviousSameSender =
112	        isDirect || (prevSender !== null && prevSender === item.data.sender);
113	      prevSender = item.data.sender;
114	    }
115	
116	    return items;
117	  }, [sortedEvents, isDirect]);
118	
119	  const handleScrollToEvent = useCallback(
120	    (eventId: string) => {
121	      const index = eventsWithDividers.findIndex(
122	        (item) => item.type === "event" && getEventId(item.data) === eventId,
123	      );
124	      if (index === -1) return;
125	
126	      flashListRef.current?.scrollToIndex({
127	        index,
128	        animated: true,
129	        viewPosition: 0.5,
130	      });
131	    },
132	    [eventsWithDividers],
133	  );
134	
135	  useEffect(() => {
136	    if (!scrollToEventId) return;
137	    handleScrollToEvent(scrollToEventId);
138	    setScrollToEventId(null);
139	  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
140	
141	  const handleScrollDown = () => {
142	    flashListRef.current?.scrollToEnd({ animated: true });
143	    setShowScrollDown(false);
144	  };
145	
146	  const handleOnScroll = ({
147	    nativeEvent,
148	  }: NativeSyntheticEvent<NativeScrollEvent>) => {
149	    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
150	    visibleHeightRef.current = layoutMeasurement.height;
151	
152	    // Paginate when within 2x visible height of the top
153	    const nearTop = contentOffset.y < layoutMeasurement.height * 2;
154	    if (nearTop && !isPaginatingRef.current && !reachedStartRef.current) {
155	      loadMoreMessages();
156	    }
157	
158	    const paddingToBottom = 100;
159	    const atBottom =
160	      layoutMeasurement.height + contentOffset.y >=
161	      contentSize.height - paddingToBottom;
162	    isAtBottomRef.current = atBottom;
163	    if (!atBottom) return;
164	    setShowScrollDown(false);
165	    markAsRead();
166	  };
