169	    // Auto-paginate if content doesn't fill the viewport (initial fill)
170	    if (
171	      contentHeight > 0 &&
172	      visibleHeightRef.current > 0 &&
173	      contentHeight < visibleHeightRef.current &&
174	      !isPaginatingRef.current &&
175	      !reachedStartRef.current
176	    ) {
177	      loadMoreMessages();
178	    }
179	
180	    if (isPaginatingRef.current) return;
181	
182	    const lastEvent = sortedEvents[sortedEvents.length - 1];
183	    const lastEventKey = lastEvent
