192	    scrollTimeoutRef.current = setTimeout(() => {
193	      flashListRef.current?.scrollToEnd({ animated: true });
194	    }, 100);
195	  };
196	
197	  useEffect(() => {
198	    const lastEvent = sortedEvents[sortedEvents.length - 1];
199	    const lastEventKey = lastEvent
200	      ? (getItemUniqueKey(lastEvent) ?? undefined)
201	      : undefined;
202	    const isNewMessageAtBottom = lastEventKey !== lastBottomEventKeyRef.current;
203	    lastBottomEventKeyRef.current = lastEventKey;
204	    if (!isNewMessageAtBottom || isAtBottomRef.current || lastEvent?.isOwn) {
205	      return;
206	    }
207	    setShowScrollDown(true);
208	  }, [sortedEvents]);
209	
210	  const renderItem = useCallback(
211	    ({ item }: { item: TimelineListItem }) => {
212	      if (item.type === "divider") {
213	        return <DateDivider date={item.date} />;
214	      }
215	
216	      if (item.type === "group") {
217	        return <GroupedInfoMessages events={item.events} roomId={roomId} />;
218	      }
219	
220	      return (
