227	      );
228	    },
229	    [roomId, openMemberDetails],
230	  );
231	
232	  useEffect(() => {
233	    return () => {
234	      setReactionsPayload(null);
235	      setSeenByUsers(null);
236	      setScrollToEventId(null);
237	      setShieldPayload(null);
238	    };
239	  }, []);
240	
241	  return (
242	    <>
243	      <KeyboardAvoidingView style={styles.flex} behavior="padding">
244	        {!!violatingUsers.length && (
245	          <RoomIdentityBanner
246	            users={violatingUsers}
247	            isLoading={isPinViolatingUsersLoading}
248	            onDismiss={pinViolatingUsers}
249	          />
250	        )}
251	        <FlashList
252	          ref={flashListRef}
253	          data={eventsWithDividers}
254	          keyExtractor={(item) => {
255	            if (item.type === "divider") return item.id;
256	            if (item.type === "group") return item.id;
257	
258	            return getItemUniqueKey(item.data) ?? "";
259	          }}
260	          maintainVisibleContentPosition={{
261	            startRenderingFromBottom: true,
262	          }}
263	          contentContainerStyle={styles.listContent}
264	          onContentSizeChange={handleContentSizeChange}
265	          onScroll={handleOnScroll}
266	          renderItem={renderItem}
267	        />
268	
269	        <RoomInput roomId={roomId} />
270	      </KeyboardAvoidingView>
271	
272	      <MessageContentBottomSheet roomId={roomId} />
273	
274	      <MemberDetailsBottomSheet
275	        isBottomSheetOpen={isBottomSheetOpen}
276	        selectedMember={selectedMember}
277	        roomId={roomId}
278	        onClose={closeMemberDetails}
279	      />
280	
281	      {showScrollDown && (
282	        <Block
283	          absolute
284	          offsets={{ right: 0, bottom: 100 }}
285	          align="center"
286	          justify="center"
287	          width="100%"
288	        >
289	          <Button.Outline size="medium" onPress={handleScrollDown}>
290	            <Text>New messages</Text>
291	            <Image source={require("assets/icons/arrow-down.png")} />
292	          </Button.Outline>
293	        </Block>
294	      )}
295	
296	      <SeenByBottomSheet
297	        isOpen={!!seenByUsers}
298	        users={seenByUsers ?? []}
299	        onClose={() => setSeenByUsers(null)}
300	      />
301	
302	      <ReactionsBottomSheet
303	        isOpen={!!reactionsPayload}
304	        reactions={reactionsPayload ?? []}
305	        onClose={() => setReactionsPayload(null)}
306	      />
307	
308	      <ShieldModal
309	        visible={!!shieldPayload}
310	        onClose={() => setShieldPayload(null)}
311	        isRed={shieldPayload?.isRed ?? false}
312	        message={shieldPayload?.message ?? ""}
313	      />
314	    </>
315	  );
316	};
