import {
  Block,
  type BlockProps,
  Text,
  useAnimateSequence,
  useLoopAnimation,
} from "@prototyp/skeletor";
import { type FC, useEffect } from "react";
import { Easing } from "react-native";
import { Colors, TextSize } from "shared/styles";

interface Props {
  text?: string;
  isFullScreen?: boolean;
  width?: number;
  height?: number;
}

export const Loading: FC<Props> = ({
  text,
  isFullScreen = true,
  width = 40,
  height = 40,
}) => {
  const style: BlockProps = isFullScreen
    ? {
        absolute: true,
        offsets: [0, 0, 0, 0],
        zIndex: 9999,
        background: "#000000B3",
      }
    : {};
  const sequence = useAnimateSequence(
    { rotation: ["0deg", "360deg"] },
    { duration: 1000, easing: Easing.linear },
  );
  const rotate = useLoopAnimation(sequence);

  useEffect(() => {
    rotate.start();
  }, []);

  return (
    <Block flex={1} justify="center" align="center" gap={12} {...style}>
      <Block
        animations={rotate.animations}
        width={width}
        height={height}
        border={{
          borderRadius: 48,
          borderWidth: 2,
          borderLeftColor: Colors.white20,
          borderColor: Colors.primary,
        }}
        background="transparent"
      />
      {text && <Text size={TextSize.small}>{text}</Text>}
    </Block>
  );
};

