      const isMsgLike =
        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
      if (!isMsgLike) {
        prevSender = null;
        continue;
      }
      item.isPreviousSameSender =
        isDirect || (prevSender !== null && prevSender === item.data.sender);
      prevSender = item.data.sender;
    }

    if (isPaginating || reachedStart) {
      const indicator: TimelineListItem = isPaginating
        ? { type: "pagination-indicator", status: "loading" }
        : { type: "pagination-indicator", status: "end-reached" };
      return [indicator, ...items];
    }

    return items;
  }, [sortedEvents, isDirect, isPaginating, reachedStart]);

