          ref={flashListRef}
          data={eventsWithDividers}
          keyExtractor={(item) => {
            if (item.type === "pagination-indicator")
              return "pagination-indicator";
            if (item.type === "divider") return item.id;
            if (item.type === "group") return item.id;

